{"command":"cd /tmp && python3 - <<'EOF'
import socket, struct, random

def q(name, server, qtype=1, timeout=2):
    tid = random.randint(0,65535)
    header = struct.pack(">HHHHHH", tid, 0x0100, 1, 0, 0, 0)
    qname = b"".join(bytes([len(p)])+p.encode() for p in name.split(".")) + b"\x00"
    pkt = header + qname + struct.pack(">HH", qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(timeout)
    try:
        s.sendto(pkt, (server, 53))
        data, _ = s.recvfrom(4096)
        return data
    except Exception as e:
        return None
    finally:
        s.close()

def parse_ips(data):
    # crude: find A-record 4-byte answers
    ips = []
    # skip header+question by parsing
    _, flags, qd, an, ns, ar = struct.unpack(">HHHHHH", data[:12])
    off = 12
    def skip_name(off):
        while True:
            l = data[off]
            if l == 0: return off+1
            if l & 0xC0 == 0xC0: return off+2
            off += 1 + l
    for _ in range(qd):
        off = skip_name(off); off += 4
    for _ in range(an+ns+ar):
        off = skip_name(off)
        if off+10 > len(data): break
        typ, cls, ttl, rdlen = struct.unpack(">HHIH", data[off:off+10])
        off += 10
        rd = data[off:off+rdlen]; off += rdlen
        if typ == 1 and rdlen == 4:
            ips.append(".".join(str(b) for b in rd))
        elif typ in (5,2) and rdlen:
            pass
    return ips

for server in ["127.0.0.11", "192.168.65.7"]:
    print("== server", server)
    for name in ["prices.internal", "commons.local", "prices.internal.", "internal"]:
        d = q(name, server)
        if d: print(" ", name, "->", parse_ips(d), "rcodes", struct.unpack(">H", d[2:4])[0] & 0xF)
        else: print(" ", name, "-> no response")
# PTR sweep on subnet
print("== PTR sweep 192.168.48.1-15")
for i in range(1,16):
    d = q(f"{i}.48.168.192.in-addr.arpa", "127.0.0.11", qtype=12)
    if d:
        # crude PTR name extraction
        txt = d.decode('latin1')
        import re
        m = re.findall(r'[\x20-\x7e]{4,}', txt[12:])
        if m: print("  .%d:" % i, m[:3])
EOF"}

